const postStarted = $('Start / Resume Run').isExecuted;
const postResumed = $('Resume Existing Session').isExecuted;
const postHandoff = $('Start New Session from Handoff').isExecuted;

if (!postStarted && !postResumed && !postHandoff) {
  const existingRun = String($json.run_id ?? '').trim();

  return [{
    json: {
      ...$json,
      run_id: existingRun,
      route: existingRun ? 'running' : 'start_error',
      error: existingRun
        ? String($json.error ?? '')
        : 'Hermes run_id is empty; status request was skipped.',
      error_code: existingRun
        ? String($json.error_code ?? '')
        : 'run_id_missing'
    }
  }];
}

// Для retry берём состояние Retry Controller,
// чтобы сохранить retry_count/max_retries/delays и session state.
const retryState = $('Retry Controller').isExecuted
  ? $('Retry Controller').last().json
  : null;

const base = retryState
  ? retryState
  : (
      postHandoff
        ? $('Build Compression Handoff').last().json
        : (
            postResumed
              ? $('Evaluate Status').last().json
              : $('Normalize Request').last().json
          )
    );

const raw = $json?.body ?? $json?.data ?? $json;

const resumedSession =
  postResumed &&
  String($('Evaluate Status').last().json.route ?? '') === 'restart_session';

return [{
  json: validate(
    (postResumed || postHandoff || retryState)
      ? {
          ...base,
          poll_count: 0,
          run_id: ''
        }
      : base,
    raw,
    resumedSession
  )
}];

function parse(value) {
  if (typeof value !== 'string') {
    return value && typeof value === 'object' ? value : {};
  }

  try {
    return JSON.parse(value);
  } catch (_) {
    return { error: value };
  }
}

function errorOf(r) {
  const raw = r.error ?? r.message ?? '';
  const text =
    typeof raw === 'string'
      ? raw
      : String(raw?.message ?? r.details ?? '');

  const code = String(
    typeof raw === 'object' && raw
      ? (raw.code ?? r.code ?? '')
      : (r.code ?? '')
  ).toLowerCase();

  return { text, code };
}

function validate(prior, response, resumed) {
  const r = parse(response);
  const err = errorOf(r);

  const returnedRun = String(r.run_id ?? '').trim();

  const returnedSession = String(
    r.session_id ??
    r.sessionId ??
    (
      typeof r.session === 'string'
        ? r.session
        : (r.session?.session_id ?? r.session?.id ?? '')
    )
  ).trim();

  const requested = String(
    prior.requested_session_id ?? prior.session_id ?? ''
  ).trim();

  const mismatch = Boolean(
    requested &&
    returnedSession &&
    requested !== returnedSession
  );

  if (mismatch) {
    return {
      ...prior,
      run_id: '',
      session_id: requested,
      status: 'failed',
      route: 'session_mismatch',
      output: '',
      error: `Hermes returned session_id ${returnedSession}, expected ${requested}.`,
      error_code: 'session_mismatch',
      session_verified: false,
      session_mismatch: true
    };
  }

  if (!returnedRun) {
    return {
      ...prior,
      run_id: '',
      session_id: returnedSession || requested,
      status: 'failed',
      route: 'start_error',
      output: '',
      error: err.text || 'Hermes did not return run_id.',
      error_code: err.code || 'run_start_failed',
      session_verified: false,
      session_mismatch: false
    };
  }

  return {
    ...prior,
    run_id: returnedRun,
    session_id: returnedSession || requested,
    status: String(r.status ?? 'started').toLowerCase(),
    route: 'running',
    output: String(r.output ?? r.response ?? r.content ?? ''),
    error: err.text,
    error_code: err.code,
    resumed: Boolean(resumed),
    session_verified:
      !requested ||
      !returnedSession ||
      returnedSession === requested,
    session_mismatch: false
  };
}

function parse(value) {
  if (typeof value !== 'string') return value && typeof value === 'object' ? value : {};
  try { return JSON.parse(value); } catch (_) { return { error: value }; }
}
function baseState() {
  if ($('Evaluate Status').isExecuted) return $('Evaluate Status').last().json;
  if ($('Capture Run Response').isExecuted) return $('Capture Run Response').last().json;
  return $('Normalize Request').last().json;
}

const envelope = $json ?? {};
const r = parse(envelope?.body ?? envelope?.data ?? envelope);
const prior = baseState();
const status = String(r.status ?? '').toLowerCase();
const raw = r.error ?? r.message ?? r.details ?? r.detail ?? '';
const errorText = typeof raw === 'string' ? raw : String(raw?.message ?? raw?.detail ?? r.details ?? '');
const errorCode = String(
  typeof raw === 'object' && raw
    ? (raw.code ?? r.code ?? '')
    : (r.code ?? '')
).toLowerCase();
const lower = errorText.toLowerCase();

const envelopeHttp = Number(
  envelope.statusCode ?? envelope.status_code ?? envelope.httpCode ?? envelope.http_code ?? NaN
);
const bodyHttp = Number(
  r.statusCode ?? r.status_code ?? r.httpCode ?? r.http_code ?? NaN
);
const match = errorText.match(/\b(4\d\d|5\d\d)\b/);
const httpCode = Number.isFinite(envelopeHttp) ? envelopeHttp
  : Number.isFinite(bodyHttp) ? bodyHttp
  : (match ? Number(match[1]) : null);

const runNotFound =
  httpCode === 404 ||
  errorCode === 'run_not_found' ||
  errorCode === 'not_found' ||
  lower.includes('run not found') ||
  lower.includes('run_not_found');

const transientCodes = new Set([408,409,425,429,500,502,503,504,529]);
const transientWords = ['temporarily overloaded','upstream error','upstream request failed','service unavailable','overloaded','timeout','timed out','connection reset','connection refused','rate limit','too many requests'];
const transient = !runNotFound && status === 'failed' && (transientCodes.has(httpCode) || transientWords.some((x) => lower.includes(x)));
const polls = Number(prior.poll_count ?? 0) + 1;

let route = 'unknown';
if (runNotFound) route = prior.requested_session_id ? 'restart_session' : 'start_new';
else if (status === 'completed') route = 'completed';
else if (status === 'cancelled' || status === 'canceled') route = 'cancelled';
else if (transient) route = 'transient_error';
else if (status === 'failed') route = 'permanent_failure';
else if (['running','started','queued','waiting_for_approval'].includes(status)) route = polls >= Number(prior.max_polls ?? 40) ? 'timeout' : 'running';

const nextRunId = runNotFound ? '' : String(r.run_id ?? prior.run_id ?? '').trim();
const nextSessionId = String(r.session_id ?? prior.session_id ?? prior.requested_session_id ?? '').trim();

return [{ json: {
  ...prior,
  run_id: nextRunId,
  session_id: nextSessionId,
  status,
  output: String(r.output ?? r.response ?? r.content ?? ''),
  error: errorText,
  error_code: errorCode,
  http_code: httpCode,
  run_not_found: runNotFound,
  transient_error: transient,
  poll_count: polls,
  route
} }];

