const retries=Number($json.retry_count??0);
const max=Number($json.max_retries??3);
const delays=Array.isArray($json.retry_delays)?$json.retry_delays: [15,30,60,120,300];
if(retries>=max) return [{json:{...$json,retry_exhausted:true,route:'provider_unavailable',
final_status:'failed_provider_unavailable',failure_reason:`Provider remained unavailable after ${max} retries.`}}];
const next=retries+1;
return [{json:{...$json,retry_count:next,retry_delay_seconds:Number(delays[Math.min(next-1,delays.length-1)]??30),retry_exhausted:false}}];

const saved = $('Load Task State — Run Context').first().json ?? {};
const result = $('Capture Run Response').last().json ?? {};
const request = $('Normalize Request').last().json ?? {};

const state = {
  ...saved,
  state_key: String(saved.state_key ?? request.state_key ?? ''),
  service_model: String(request.service_model ?? ''),
  service_provider: String(request.service_provider ?? ''),
  plan_json: String(saved.plan_json ?? ''),
  task_index: Number(saved.task_index ?? 0),
  task_attempt: Number(saved.task_attempt ?? 1),
  status: String(saved.status ?? 'active'),
  review_feedback: String(saved.review_feedback ?? ''),
  last_review_score: Number(saved.last_review_score ?? 0),
  last_review_reason: String(saved.last_review_reason ?? ''),
  reviewer_run_id: String(saved.reviewer_run_id ?? ''),
  reviewer_status: String(saved.reviewer_status ?? ''),
  reviewer_session_id: String(saved.reviewer_session_id ?? ''),
  worker_run_id: String(saved.worker_run_id ?? ''),
  worker_status: String(saved.worker_status ?? ''),
  worker_session_id: String(saved.worker_session_id ?? ''),
  architect_run_id: String(saved.architect_run_id ?? ''),
  architect_status: String(saved.architect_status ?? ''),
  architect_session_id: String(saved.architect_session_id ?? '')
};

const role = String(result.role ?? request.role ?? '').toLowerCase();
const runId = String(result.run_id ?? '').trim();
const sessionId = String(result.session_id ?? '').trim();
const status = String(result.status ?? '').trim();
const route = String(result.route ?? '').trim();
const clearingStaleRun = route === 'restart_session' || route === 'start_new';

if (role === 'worker') {
  state.worker_run_id = clearingStaleRun ? '' : (runId || state.worker_run_id);
  if (sessionId) state.worker_session_id = sessionId;
  if (status) state.worker_status = status;
}
if (role === 'reviewer') {
  state.reviewer_run_id = clearingStaleRun ? '' : (runId || state.reviewer_run_id);
  if (sessionId) state.reviewer_session_id = sessionId;
  if (status) state.reviewer_status = status;
}
if (role === 'architect') {
  state.architect_run_id = clearingStaleRun ? '' : (runId || state.architect_run_id);
  if (sessionId) state.architect_session_id = sessionId;
  if (status) state.architect_status = status;
}

return [{json: state}];

const saved = $('Load Task State — Status').first().json ?? {};
const result = $('Evaluate Status').last().json ?? {};
const request = $('Normalize Request').last().json ?? {};

const route = String(result.route ?? '').trim();
const clearingStaleRun = route === 'restart_session' || route === 'start_new';

const state = {
  ...saved,
  state_key: String(saved.state_key ?? request.state_key ?? ''),
  plan_json: String(saved.plan_json ?? ''),
  task_index: Number(saved.task_index ?? 0),
  task_attempt: Number(saved.task_attempt ?? 1),
  status: String(saved.status ?? 'active'),
  review_feedback: String(saved.review_feedback ?? ''),
  last_review_score: Number(saved.last_review_score ?? 0),
  last_review_reason: String(saved.last_review_reason ?? ''),
  reviewer_run_id: String(saved.reviewer_run_id ?? ''),
  reviewer_status: String(saved.reviewer_status ?? ''),
  reviewer_session_id: String(saved.reviewer_session_id ?? ''),
  worker_run_id: String(saved.worker_run_id ?? ''),
  worker_status: String(saved.worker_status ?? ''),
  worker_session_id: String(saved.worker_session_id ?? ''),
  architect_run_id: String(saved.architect_run_id ?? ''),
  architect_status: String(saved.architect_status ?? ''),
  architect_session_id: String(saved.architect_session_id ?? '')
};

const role = String(result.role ?? request.role ?? '').toLowerCase();
const runId = String(result.run_id ?? '').trim();
const sessionId = String(result.session_id ?? '').trim();
const status = String(result.status ?? '').trim();

if (role === 'worker') {
  state.worker_run_id = clearingStaleRun ? '' : (runId || state.worker_run_id);
  if (sessionId) state.worker_session_id = sessionId;
  if (status) state.worker_status = status;
}
if (role === 'reviewer') {
  state.reviewer_run_id = clearingStaleRun ? '' : (runId || state.reviewer_run_id);
  if (sessionId) state.reviewer_session_id = sessionId;
  if (status) state.reviewer_status = status;
}
if (role === 'architect') {
  state.architect_run_id = clearingStaleRun ? '' : (runId || state.architect_run_id);
  if (sessionId) state.architect_session_id = sessionId;
  if (status) state.architect_status = status;
}

return [{json: state}];

// FIX: восстановлено чтение реального exit code из маркера __HERMES_EXIT__=N
// (shell всегда возвращает 0 из-за финального 'exit 0', реальный код — в stdout).
const prior =
  $('Mark Compression Target — Start').isExecuted
    ? $('Mark Compression Target — Start').last().json
    : $('Mark Compression Target — Resume').last().json;

const stdout = String($json.stdout ?? '').trim();
const stderr = String($json.stderr ?? '').trim();
const shellExitCode = Number($json.exitCode ?? $json.code ?? 0);

const exitMatch = stdout.match(/__HERMES_EXIT__=(\d+)/);
const exitCode = exitMatch ? Number(exitMatch[1]) : shellExitCode;

function parseJson(value) {
  if (!value) return {};
  if (typeof value === 'object' && value !== null) return value;
  try { return JSON.parse(String(value)); } catch { return {}; }
}

let response = {};
let diagnostic = '';
let hermesStdout = '';
let hermesStderr = '';

const stdoutMarker = '__HERMES_STDOUT__';
const stderrMarker = '__HERMES_STDERR__';

const stdoutPos = stdout.indexOf(stdoutMarker);

if (stdoutPos >= 0) {
  const afterStdoutMarker = stdout.slice(stdoutPos + stdoutMarker.length);
  const stderrPos = afterStdoutMarker.indexOf(stderrMarker);
  if (stderrPos >= 0) {
    hermesStdout = afterStdoutMarker.slice(0, stderrPos).trim();
    hermesStderr = afterStdoutMarker.slice(stderrPos + stderrMarker.length).trim();
  } else {
    hermesStdout = afterStdoutMarker.trim();
  }
} else {
  hermesStdout = stdout;
}

response = parseJson(hermesStdout);

if (!Object.keys(response).length && hermesStdout) {
  diagnostic = hermesStdout;
}

const responseError = response.error ?? response.message ?? response.detail ?? '';

const errorText = String(
  typeof responseError === 'string'
    ? responseError
    : (responseError?.message ?? hermesStderr ?? stderr ?? (exitCode !== 0 ? `Compression command exited with code ${exitCode}.` : ''))
).trim();

const status = String(response.compression_status ?? response.status ?? '').toLowerCase();
const commitStatus = String(response.commit_status ?? '').toLowerCase();

const failed =
  Boolean(response.compression_failed) ||
  exitCode !== 0 ||
  ['failed', 'aborted', 'cancelled', 'canceled'].includes(status) ||
  ['failed', 'aborted'].includes(commitStatus);

const completed =
  !failed && (
    Boolean(response.compression_completed) ||
    status === 'completed' ||
    commitStatus === 'committed'
  );

const sessionId = String(
  response.compression_session_id ??
  response.session_id ??
  response.requested_session_id ??
  prior.session_id ??
  prior.requested_session_id ??
  ''
).trim();

return [{
  json: {
    ...prior,
    compression_run_id: '',
    compression_session_id: sessionId,
    compression_status: failed ? 'failed' : (completed ? 'completed' : (status || 'unknown')),
    compression_error: errorText,
    compression_output: response.compression_output ?? response.output ?? hermesStdout,
    compression_stdout: hermesStdout,
    compression_stderr: hermesStderr || stderr,
    compression_exit_code: exitCode,
    compression_response: response,
    compression_diagnostic: diagnostic || errorText || hermesStderr || stderr,
    compression_failed: failed,
    compression_completed: completed,
    session_id: sessionId || String(prior.session_id ?? '').trim(),
    requested_session_id: sessionId || String(prior.requested_session_id ?? '').trim(),
    run_id: ''
  }
}];

const current = $json ?? {};
const role = String(current.role ?? '').trim().toLowerCase();
const persisted = $('Load Task State — Run Context').isExecuted
  ? ($('Load Task State — Run Context').first().json ?? {})
  : {};

function roleSession(state, roleName) {
  if (roleName === 'worker') return String(state.worker_session_id ?? '').trim();
  if (roleName === 'reviewer') return String(state.reviewer_session_id ?? '').trim();
  if (roleName === 'architect') return String(state.architect_session_id ?? '').trim();
  return '';
}

const previousSession =
  String(current.compression_target_session_id ?? '').trim() ||
  roleSession(persisted, role) ||
  String(current.session_id ?? current.requested_session_id ?? '').trim();

const reason = String(
  current.compression_error ||
  current.compression_stderr ||
  current.compression_stdout ||
  `Compression failed with exit code ${current.compression_exit_code ?? 'unknown'}.`
).trim();

const handoff = [
  'SESSION HANDOFF — continue in a fresh Hermes session.',
  '',
  'The previous Hermes session could not be safely compressed, so continuation was moved to a new session.',
  'Do NOT restart the task from scratch.',
  'Preserve the existing task objective, constraints, progress and expected output format.',
  '',
  'PREVIOUS SESSION ID:',
  previousSession || '(not available)',
  '',
  'COMPRESSION FAILURE:',
  reason,
  '',
  'ORIGINAL TASK INPUT:',
  String(current.input || current.resume_input || '(not available)').trim(),
  '',
  'CONTINUE:',
  'Resume the task from the information above. Verify the current repository/workspace state before making changes.',
].join('\n');

return [{
  json: {
    ...current,
    handoff_input: handoff,
    handoff_from_session_id: previousSession,
    compression_handoff: true,
    run_id: '',
    session_id: '',
    requested_session_id: '',
  },
}];

const login = $('Hermes Dashboard Login').last();
const response = login?.json ?? {};
const headers = response.headers ?? {};

const getHeader = (name) => {
  const key = Object.keys(headers).find((k) => k.toLowerCase() === name.toLowerCase());
  return key ? headers[key] : undefined;
};

const rawSetCookie = getHeader('set-cookie');
const values = Array.isArray(rawSetCookie) ? rawSetCookie : [rawSetCookie];
const cookieParts = [];

for (const value of values) {
  if (value == null) continue;
  const text = String(value).trim();
  if (!text) continue;
  for (const part of text.split(/,(?=\s*[^;,\s=]+\s*=)/g)) {
    const cookie = part.split(';', 1)[0].trim();
    if (cookie) cookieParts.push(cookie);
  }
}

const unique = new Map();
for (const cookie of cookieParts) {
  const eq = cookie.indexOf('=');
  if (eq <= 0) continue;
  const name = cookie.slice(0, eq).trim();
  const value = cookie.slice(eq + 1).trim();
  if (name && value) unique.set(name, `${name}=${value}`);
}

const hermes_cookie = [...unique.values()].join('; ');

if (!hermes_cookie) {
  throw new Error(
    'Hermes Dashboard Login returned no usable Set-Cookie. ' +
    `HTTP=${response.statusCode ?? 'unknown'} ` +
    `Headers=${JSON.stringify(headers)} ` +
    `Body=${JSON.stringify(response.body ?? null)}`
  );
}

return [{ json: { ...response, hermes_cookie } }];

const current = $json ?? {};
const role = String(current.role ?? '').trim().toLowerCase();
const target = $('Mark Compression Target — Start').isExecuted
  ? $('Mark Compression Target — Start').last().json ?? {}
  : ($('Mark Compression Target — Resume').last().json ?? {});

const persisted = $('Load Task State — Run Context').isExecuted
  ? ($('Load Task State — Run Context').first().json ?? {})
  : {};

function roleSession(state, roleName) {
  if (roleName === 'worker') return String(state.worker_session_id ?? '').trim();
  if (roleName === 'reviewer') return String(state.reviewer_session_id ?? '').trim();
  if (roleName === 'architect') return String(state.architect_session_id ?? '').trim();
  return '';
}

const session_id =
  roleSession(persisted, role) ||
  roleSession(target, role) ||
  String(target.session_id ?? target.requested_session_id ?? current.session_id ?? current.requested_session_id ?? '').trim();

const ticket = String(current.ticket ?? '').trim();

if (!session_id) {
  throw new Error(`Compress Session: session_id is missing for role=${role || 'unknown'}.`);
}

if (!ticket) {
  throw new Error('Compress Session: WS ticket is missing.');
}

const payload = { session_id, ticket, keep_recent: 20, timeout: 120 };

const compression_payload = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');

return [{
  json: { ...current, compression_target_session_id: session_id, session_id, compression_payload }
}];
